import { useState, useEffect } from 'react';
import useNotes from '../hooks/useNotes';
import Header from '../components/Header';
import TagFilter from '../components/TagFilter';
import NoteForm from '../components/NoteForm';
import NoteList from '../components/NoteList';

export default function NotesPage() {
  const { notes, loading, error, createNote, deleteNote, setTag } = useNotes();

  if (loading) {
    return <div className="p-6 text-center text-gray-500">Loading notes…</div>;
  }

  if (error) {
    return <div className="p-6 text-center text-red-600">{error}</div>;
  }

  return (
    <div className="max-w-5xl mx-auto p-6">
      <Header count={notes?.length ?? 0} />
      <TagFilter onSelectTag={setTag} />
      <NoteForm onCreated={createNote} />
      <NoteList notes={notes} onDelete={deleteNote} />
    </div>
  );
}

