import { useState } from 'react';
import api from '../lib/api';

export default function NoteForm({ onCreate }) {
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [tags, setTags] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);

  const handleSubmit = (event) => {
    event.preventDefault();
    setSubmitting(true);
    setError(null);
    const noteTags = tags.split(',').map((tag) => tag.trim());
    onCreate(title, body, noteTags)
      .then(() => {
        setTitle('');
        setBody('');
        setTags('');
      })
      .catch((err) => {
        setError(err?.response?.data?.detail ?? 'Failed to create note');
      })
      .finally(() => {
        setSubmitting(false);
      });
  };

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-4 p-6 rounded-lg border border-gray-200 bg-white">
      <input
        type="text"
        value={title}
        onChange={(event) => setTitle(event.target.value)}
        placeholder="Note title"
        className="w-full p-2 pl-10 text-sm text-gray-700 border border-gray-200 rounded-lg focus:ring-gray-500 focus:border-gray-500"
      />
      <textarea
        value={body}
        onChange={(event) => setBody(event.target.value)}
        placeholder="Note body"
        className="w-full p-2 pl-10 text-sm text-gray-700 border border-gray-200 rounded-lg focus:ring-gray-500 focus:border-gray-500"
      />
      <input
        type="text"
        value={tags}
        onChange={(event) => setTags(event.target.value)}
        placeholder="Tags (comma-separated)"
        className="w-full p-2 pl-10 text-sm text-gray-700 border border-gray-200 rounded-lg focus:ring-gray-500 focus:border-gray-500"
      />
      {submitting ? (
        <button type="submit" disabled className="w-full p-2 pl-5 pr-5 bg-gray-500 text-gray-100 text-sm rounded-lg">
          Submitting…
        </button>
      ) : (
        <button type="submit" className="w-full p-2 pl-5 pr-5 bg-blue-500 text-gray-100 text-sm rounded-lg hover:bg-blue-700">
          Create Note
        </button>
      )}
      {error && <div className="text-red-600">{error}</div>}
    </form>
  );
}

