import { useState, useEffect } from 'react';
import api from '../lib/api';

export default function TagFilter({ onSelectTag }) {
  const [tags, setTags] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedTag, setSelectedTag] = useState(null);

  useEffect(() => {
    let active = true;
    api
      .get('/tags')
      .then((res) => {
        if (active) setTags(res.data ?? []);
      })
      .catch((err) => {
        if (active) setError(err?.response?.data?.detail ?? 'Failed to load tags');
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
  }, []);

  const handleTagClick = (tag) => {
    setSelectedTag(tag);
    onSelectTag(tag);
  };

  const handleClearClick = () => {
    setSelectedTag(null);
    onSelectTag(null);
  };

  if (loading) {
    return <div className="p-6 text-center text-gray-500">Loading tags…</div>;
  }

  if (error) {
    return <div className="p-6 text-center text-red-600">{error}</div>;
  }

  return (
    <div className="flex flex-wrap gap-2">
      {tags.map((tag) => (
        <button
          key={tag}
          className={`px-4 py-2 rounded-lg ${selectedTag === tag ? 'bg-blue-500 text-white' : 'bg-gray-100 text-gray-600'}`}
          onClick={() => handleTagClick(tag)}
        >
          {tag}
        </button>
      ))}
      {selectedTag && (
        <button
          className="px-4 py-2 rounded-lg bg-gray-100 text-gray-600"
          onClick={handleClearClick}
        >
          Clear
        </button>
      )}
    </div>
  );
}

