import { useState, useEffect } from 'react';
import api from '../lib/api';

export default function useNotes() {
  const [notes, setNotes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [tag, setTag] = useState(null);

  useEffect(() => {
    let active = true;
    const fetchNotes = async () => {
      try {
        const response = await api.get(tag ? `/notes?tag=${tag}` : '/notes');
        if (active) setNotes(response.data ?? []);
      } catch (err) {
        if (active) setError(err?.response?.data?.detail ?? 'Failed to load notes');
      } finally {
        if (active) setLoading(false);
      }
    };
    fetchNotes();
    return () => {
      active = false;
    };
  }, [tag]);

  const createNote = async (newNote) => {
    try {
      const response = await api.post('/notes', newNote);
      setNotes((prevNotes) => [...prevNotes, response.data]);
    } catch (err) {
      setError(err?.response?.data?.detail ?? 'Failed to create note');
    }
  };

  const deleteNote = async (id) => {
    try {
      await api.delete(`/notes/${id}`);
      setNotes((prevNotes) => prevNotes.filter((note) => note.id !== id));
    } catch (err) {
      setError(err?.response?.data?.detail ?? 'Failed to delete note');
    }
  };

  const setTagFilter = (newTag) => {
    setTag(newTag);
    setLoading(true);
    setError(null);
  };

  return { notes, loading, error, createNote, deleteNote, setTag: setTagFilter };
}

